title:
export function createContext(defaultValue) {
  const context = {
    $$typeof: REACT_CONTEXT_TYPE,
    _currentValue: defaultValue,  // 현재 값 (기본값으로 초기화)
    Provider: null,
    Consumer: null,
  }

  context.Provider = {
    $$typeof: REACT_PROVIDER_TYPE,
    _context: context,  // Provider가 context를 역참조
  }

  context.Consumer = context  // Consumer는 context 자체!

  return context
}

