title:
function readContext(context) {
  const value = context._currentValue  // 현재 값 읽기

  // 이 Fiber의 dependencies에 context 등록
  const contextItem = {
    context: context,
    memoizedValue: value,
    next: null,
  }

  // dependencies는 연결 리스트
  currentlyRenderingFiber.dependencies = {
    lanes: NoLanes,
    firstContext: contextItem,
  }

  return value
}

